{"code": "from PIL import Image, UnidentifiedImageError
import os

# Try loading some images from both categories
train_dir = 'data_small/cats_and_dogs/train'

categories = ['cats', 'dogs']
for category in categories:
    cat_dir = os.path.join(train_dir, category)
    files = os.listdir(cat_dir)[:5]  # Check first 5 files
    print(f"\nChecking {category}:")
    for f in files:
        filepath = os.path.join(cat_dir, f)
        try:
            with Image.open(filepath) as img:
                img.load()
                print(f"  {f}: OK")
        except UnidentifiedImageError as e:
            print(f"  {f}: CORRUPTED - {e}")
        except Exception as e:
            print(f"  {f}: ERROR - {e}")"}

